{
  "scene": "Urban two-lane one-way road with a bus stop on the left and a sidewalk with parked bicycles on the right; a pedestrian crosswalk is ahead.",
  "lane_count": 2,
  "ego_lane_index": 2,
  "scene_evidence": "partial",
  "left_boundary": {
    "observation": "Photo 1 shows a solid white line running down the road separating two lanes of the same direction, visible from the bottom of the image to the crosswalk ahead. Photo 2 shows the same solid white line immediately to the left of my car, continuing ahead.",
    "color": "white",
    "pattern": "solid",
    "near_line": "not_applicable",
    "curb": "no",
    "role": "lane_line",
    "evidence": "full"
  },
  "right_boundary": {
    "observation": "Photo 1 shows the right side of the road bordered by a raised curb with a yellow top and a sidewalk with parked bicycles and scooters. Photo 2 shows the same curb and sidewalk immediately to the right of my car.",
    "color": "white",
    "pattern": "solid",
    "near_line": "not_applicable",
    "curb": "yes",
    "role": "edge_line",
    "evidence": "partial"
  },
  "lane_markings": [
    {
      "observation": "Photo 2 shows a white arrow in my lane at the bottom left of the image, partially visible, pointing straight ahead; Photo 1 shows the same marking further ahead.",
      "marking": "arrow:straight",
      "evidence": "partial"
    },
    {
      "observation": "Photo 1 and Photo 2 show a pedestrian crosswalk with white stripes crossing my lane ahead.",
      "marking": "line:crosswalk",
      "evidence": "full"
    }
  ],
  "cross_check": {
    "close_up": "the same in both photos",
    "position": "lane count 2 and ego lane index 2 agree with a lane line on the left and an edge/curb on the right",
    "roles": "white solid line on the left is a same-direction lane line; white solid edge with curb on the right is an edge line",
    "markings": "the straight arrow in my lane is consistent with the lane boundaries and no conflicting markings are present",
    "unseen": "no attribute was reported that was not actually seen",
    "result": "consistent"
  },
  "element_rules": [
    {
      "element": "left_boundary",
      "rule_id": "CN-6.2.1",
      "meaning": "A no-crossing lane line separates vehicles travelling in the same direction and prohibits vehicles on the solid-line side from crossing."
    },
    {
      "element": "right_boundary",
      "rule_id": "CN-4.2.2-a",
      "meaning": "A solid longitudinal marking means crossing is normally prohibited and may be crossed only in an emergency when safe."
    },
    {
      "element": "arrow:straight",
      "rule_id": "CN-5.13.1",
      "meaning": "Guide arrows indicate the direction of travel for vehicles; a straight arrow permits going straight and restricts other movements."
    },
    {
      "element": "line:crosswalk",
      "rule_id": null,
      "meaning": "A crosswalk is a line across the lane; it does not govern the seven actions."
    }
  ],
  "action_reasons": {
    "change_left": "Left boundary is a solid white lane line; CN-6.2.1 / CN-4.2.2-a prohibits crossing.",
    "change_right": "Right boundary is an edge line with a raised curb; solid marking prohibits crossing to the shoulder/sidewalk.",
    "go_straight": "Lane contains a straight guide arrow; CN-5.13.1 allows straight travel.",
    "turn_left": "Lane contains a straight guide arrow; left turn is not shown and is therefore prohibited.",
    "turn_right": "Lane contains a straight guide arrow; right turn is not shown and is therefore prohibited.",
    "u_turn": "Lane contains a straight guide arrow; U-turn is not shown and is therefore prohibited.",
    "enter_waiting_area": "No left-turn waiting area or two-way left-turn lane is visible in my lane."
  },
  "decision_check": "consistent",
  "actions": {
    "change_left": "prohibited",
    "change_right": "prohibited",
    "go_straight": "allowed",
    "turn_left": "prohibited",
    "turn_right": "prohibited",
    "u_turn": "prohibited",
    "enter_waiting_area": "not_applicable"
  },
  "advice": "Stay in the right lane; lane changes left and right are prohibited by the solid lane line and the curb/edge. The lane is marked for straight ahead only, so proceed straight and do not turn."
}

{
  "scene": "Urban multi-lane road in China with traffic keeping to the right. Ahead is an intersection with overhead guide signs indicating the next road junction. My car is in the rightmost lane of the direction of travel.",
  "lane_count": 3,
  "ego_lane_index": 3,
  "scene_evidence": "full",
  "left_boundary": {
    "observation": "Photo 1 shows a white broken lane line separating my lane from the middle lane, continuing ahead. Photo 2 shows the same white broken line immediately to the left of my lane with dashes and gaps visible.",
    "color": "white",
    "pattern": "dashed",
    "near_line": "not_applicable",
    "curb": "no",
    "role": "lane_line",
    "evidence": "full"
  },
  "right_boundary": {
    "observation": "Photo 1 shows a raised yellow curb forming the right edge of my lane with yellow painted curb, no painted lane line visible on the pavement. Photo 2 shows the same yellow curb immediately to the right of my lane.",
    "color": "yellow",
    "pattern": "none",
    "near_line": "not_applicable",
    "curb": "yes",
    "role": "edge_line",
    "evidence": "full"
  },
  "lane_markings": [
    {
      "observation": "Photo 2 shows a white right-turn arrow painted in my lane with the arrow head pointing to the right. Photo 1 shows the same arrow further ahead in the same lane.",
      "marking": "arrow:right",
      "evidence": "full"
    }
  ],
  "cross_check": {
    "close_up": "the same in both photos",
    "position": "lane count 3 and ego lane index 3 agree with a lane line on the left and an edge/curb on the right, i.e. the rightmost lane of the direction",
    "roles": "left white dashed line fits a lane line between same-direction lanes; right yellow curb fits an edge line of the roadway",
    "markings": "the right-turn arrow in the rightmost lane agrees with the edge boundary and with no left-turn waiting area",
    "unseen": "no attribute was reported that was not actually seen",
    "result": "consistent"
  },
  "element_rules": [
    {
      "element": "left_boundary",
      "rule_id": "CN-5.2.1-2",
      "meaning": "The crossable lane line separates traffic flows in the same direction and is a broken white line, so vehicles may cross it to change lanes when safe."
    },
    {
      "element": "left_boundary",
      "rule_id": "CN-4.2.2-a",
      "meaning": "A broken line means it may be crossed."
    },
    {
      "element": "right_boundary",
      "rule_id": "CN-5.4.3",
      "meaning": "The carriageway edge line marks the edge of the roadway; an edge line on the right side of the direction of travel is the boundary of the lane and is normally not crossed."
    },
    {
      "element": "arrow:right",
      "rule_id": "CN-5.13.1",
      "meaning": "Guide arrows indicate the direction of travel for vehicles, so a right arrow requires the vehicle to follow the indicated right turn direction."
    },
    {
      "element": "arrow:right",
      "rule_id": "CN-5.13.2",
      "meaning": "Guide arrows shall be marked on intersection approaches where the direction of travel is restricted, so the arrow governs the permitted movement out of the lane."
    }
  ],
  "action_reasons": {
    "change_left": "Left boundary is a broken white lane line; CN-5.2.1-2 and CN-4.2.2-a permit crossing a broken line to change lanes.",
    "change_right": "Right boundary is a raised yellow curb/edge of the roadway; crossing the edge/curb is normally prohibited.",
    "go_straight": "My lane contains a right-turn guide arrow; straight ahead is not indicated by the arrow.",
    "turn_left": "My lane contains a right-turn guide arrow; left turn is not indicated by the arrow.",
    "turn_right": "My lane contains a right-turn guide arrow; CN-5.13.1/5.13.2 require following the indicated right direction.",
    "u_turn": "My lane contains a right-turn guide arrow; U-turn is not indicated by the arrow.",
    "enter_waiting_area": "No left-turn waiting area or two-way left-turn lane is visible in my lane."
  },
  "decision_check": "consistent",
  "actions": {
    "change_left": "allowed",
    "change_right": "prohibited",
    "go_straight": "prohibited",
    "turn_left": "prohibited",
    "turn_right": "allowed",
    "u_turn": "prohibited",
    "enter_waiting_area": "not_applicable"
  },
  "advice": "You are in the rightmost lane which is marked with a right-turn arrow and bounded on the right by a raised yellow curb. Stay in the lane for the upcoming right turn; a lane change to the left is permitted via the broken white line, but changing right onto the curb/shoulder is prohibited and going straight or turning left from this lane is not allowed by the markings."
}
